'use strict';

// Generated by npm run build from every shell asset and this worker's logic.
// Updates wait for the user; never hand-edit the cache name.
const CACHE_PREFIX = 'chesno-shell-';
const CACHE_NAME = `${CACHE_PREFIX}6859a25d1c7f72967ac3986a7a687645192d8b07024c4f9987a4c4f1b77f45fb`;
const BASE = new URL('./', self.location.href);
const APP_SHELL = [
  './',
  './index.html',
  './styles.css',
  './management.css',
  './app.js',
  './model.js',
  './store.js',
  './management.js',
  './pwa.js',
  './manifest.webmanifest',
  './icons/icon192.png',
  './icons/icon512.png',
  './icons/apple-touch-icon.png'
].map(path => new URL(path, BASE).href);
const SHELL_URLS = new Set(APP_SHELL);
const INDEX_URL = new URL('./index.html', BASE).href;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    try {
      // addAll is atomic: a failed asset prevents an incomplete shell from activating.
      await cache.addAll(APP_SHELL.map(url => new Request(url, {
        credentials: 'same-origin',
        cache: 'reload'
      })));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names
      .filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME)
      .map(name => caches.delete(name)));
    // Do not claim open pages: an update must not interrupt a form or a database write.
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'APPLY_UPDATE') {
    // Sent only after an explicit click and the page's canUpdate check.
    event.waitUntil(self.skipWaiting());
  }
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== BASE.origin || !url.pathname.startsWith(BASE.pathname)) return;

  const isAppNavigation = request.mode === 'navigate' &&
    (url.pathname === BASE.pathname || url.pathname === new URL(INDEX_URL).pathname);
  if (isAppNavigation) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      return (await cache.match(INDEX_URL)) || fetch(request);
    })());
    return;
  }

  url.search = '';
  url.hash = '';
  if (!SHELL_URLS.has(url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    return (await cache.match(url.href)) || fetch(request);
  })());
});
